constructor(address controller) ZZZModule(controller) {
        assets.push(address(0));
        isAsset[address(0)] = true;
        emit AssetAdded(address(0));
    }

constructor(address controller) {
        if (controller.code.length == 0) revert InvalidConfiguration();
        access = IZZZAccess(controller);
    }

constructor(address controller, address receiver, address wrappedETH) ZZZModule(controller) {
        if (receiver.code.length == 0 || (wrappedETH != address(0) && wrappedETH.code.length == 0)) revert InvalidConfiguration();
        ledger = receiver; wrapper = wrappedETH;
        v4Executor = new ZZZV4RouteExecutor();
    }

constructor(address initialGovernance, address initialKeeper, address initialGuardian) {
        if (initialGovernance == address(0) || initialGovernance == address(this) ||
            initialKeeper == address(0) || initialGuardian == address(0)) revert InvalidConfiguration();
        governance = initialGovernance;
        bootstrap = msg.sender;
        royaltyFactory = address(new ZZZRoyaltyFactory());
        activationAssetsFactory = address(new ZZZActivationAssetsFactory());
        keepers[initialKeeper] = true;
        emit KeeperChanged(initialKeeper, true);
        guardians[initialGuardian] = true;
        emit GuardianChanged(initialGuardian, true);
    }

constructor(address controller, address poolRegistry) ZZZModule(controller) {
        if (poolRegistry == address(0) || msg.sender != access.activationAssetsFactory() ||
            IActivationAssetsFactoryIdentity(msg.sender).access() != controller) revert InvalidConfiguration();
        registry = poolRegistry;
    }

constructor(address controller, address poolRegistry, address assets) ZZZModule(controller) {
        if (poolRegistry == address(0) || msg.sender != poolRegistry || assets.code.length == 0 ||
            ZZZActivationAssets(assets).registry() != poolRegistry ||
            address(ZZZActivationAssets(assets).access()) != controller) revert InvalidConfiguration();
        registry = poolRegistry;
        activationAssets = ZZZActivationAssets(assets);
    }

constructor(address controller, address zzzToken, uint256 maximumTradeUSD) ZZZModule(controller) {
        if (zzzToken.code.length == 0 || maximumTradeUSD == 0 || maximumTradeUSD > type(uint128).max) revert InvalidConfiguration();
        zzz = zzzToken;
        maxTradeUSD = maximumTradeUSD;
        operatingTradeUSD = maximumTradeUSD;
    }

constructor(address controller) {
        access = ICanonicalController(controller);
    }

constructor(address controller, address nftController, address royaltyLedger) {
        if (controller.code.length == 0 || msg.sender != nftController || royaltyLedger.code.length == 0) {
            revert InvalidConfiguration();
        }
        access = IZZZAccess(controller);
        nft = nftController;
        royalties = royaltyLedger;
    }

constructor(address controller,address priceOracle) {
        if (msg.sender != priceOracle || controller.code.length == 0) revert Unauthorized();
        access = IZZZAccess(controller); oracle = IZZZOracle(priceOracle);
    }

constructor(address controller, address feeController) ZZZModule(controller) {
        fees = ZZZFeeController(payable(feeController));
        if (feeController.code.length == 0 || address(fees.access()) != controller || fees.FEE_INTAKE_VERSION() != 1) revert InvalidConfiguration();
    }

constructor(address controller,address positionManager_,address stateView_,address poolManager_,address permit2_,address balancer_)
        ZZZModule(controller) {
        if (positionManager_.code.length == 0 || stateView_.code.length == 0 || poolManager_.code.length == 0 ||
            permit2_.code.length == 0) revert InvalidConfiguration();
        posm = IPositionManagerMinimal(positionManager_);
        stateView = IStateViewMinimal(stateView_);
        poolManager = IPoolManagerMinimal(poolManager_);
        permit2 = IPermit2Minimal(permit2_);
        if (posm.poolManager() != poolManager_ || posm.permit2() != permit2_ ||
            stateView.poolManager() != poolManager_) revert InvalidConfiguration();
        if(balancer_.code.length==0)revert InvalidConfiguration();
        balancingRouter=ZZZLPBalancer(balancer_);
        if(address(balancingRouter.access())!=controller || address(balancingRouter.poolManager())!=poolManager_ ||
            address(balancingRouter.stateView())!=stateView_ || balancingRouter.LP_ROUTING_VERSION()!=3)revert InvalidConfiguration();
        positionExecutor=new ZZZLPPositionExecutor(controller,positionManager_,stateView_,poolManager_,permit2_,balancer_);
    }

constructor(address controller, address core, address state) ZZZModule(controller) {
        balanceMath = new ZZZLPBalanceMath();
        poolManager = IPoolManagerMinimal(core);
        stateView = IStateViewMinimal(state);
    }

constructor(address controller,address positionManager_,address stateView_,address poolManager_,address permit2_,address balancer_)
        ZZZModule(controller) {
        liquidityManager=msg.sender;posm=IPositionManagerMinimal(positionManager_);
        stateView=IStateViewMinimal(stateView_);poolManager=IPoolManagerMinimal(poolManager_);
        permit2=IPermit2Minimal(permit2_);balancingRouter=ZZZLPBalancer(balancer_);
    }

constructor(address controller) ZZZModule(controller) {
        validation = new ZZZCustodyValidation(controller);
    }

constructor(address controller) {
        access = IZZZAccess(controller);
    }

constructor(address controller, string memory baseURI,address renderer)
        ERC721("ZZZ Permanent Liquidity Rights", "ZZZLP") ZZZSeaDropToken(controller) {
        if(renderer.code.length==0 || address(ZZZNFTMetadata(renderer).access())!=controller)
            revert InvalidConfiguration();
        metadataRenderer=ZZZNFTMetadata(renderer);
        metadataRenderer.validateBaseURI(baseURI);
        metadataBase = baseURI;
        metadataConfigured = bytes(baseURI).length != 0;
        royaltyRewards = ZZZRoyaltyFactory(access.royaltyFactory()).create();
        if (royaltyRewards.canonicalController() != controller || royaltyRewards.nft() != address(this)) revert InvalidConfiguration();
        claimRouter = new ZZZClaimRouter(controller, address(this), address(royaltyRewards));
    }

constructor(address controller, address collection) ZZZModule(controller) {
        if (collection.code.length == 0 || IZZZNFTCanonicalState(collection).access() != controller) revert InvalidConfiguration();
        nft = IZZZNFTCanonicalState(collection);
    }

constructor(address controller, address sequencer) ZZZModule(controller) {
        contributionPricing = new ZZZContributionPricing(controller,address(this));
        if (sequencer != address(0)) {
            bytes32 codeHash = sequencer.codehash;
            _sequencerData(sequencer, codeHash,0);
            // A deployment admission reference is provenance, not an independent
            // review. Production qualification must separately review this pin.
            bytes32 admissionReference = keccak256(abi.encode("ZZZ_SEQUENCER_BOOTSTRAP_V1", sequencer, codeHash));
            _recordSequencer(SequencerPolicy(sequencer, codeHash, admissionReference, true));
        }
    }

constructor(address controller) ZZZModule(controller) {
        activationAssets = ZZZActivationAssets(ZZZActivationAssetsFactory(access.activationAssetsFactory()).create());
        activationEntry = new ZZZActivationEntry(controller, address(this), address(activationAssets));
    }

constructor(address controller,address initialMintRecipient) ZZZModule(controller) {
        if(initialMintRecipient==address(0) || initialMintRecipient==controller || initialMintRecipient==address(this))
            revert InvalidConfiguration();
        entry=P.EntryPolicy(100e18,5e18,500,1);
        maintenance=P.MaintenancePolicy(500,1);
        gasLimits=P.GasPolicy(180000,500000,1000000,1);
        sale=P.SalePolicy(uint128(0.05 ether),initialMintRecipient,address(0),1);
        metadata=P.MetadataPolicy(1000e18,10000e18,1);
        configurationHash=keccak256(abi.encode("ZZZ_PROTOCOL_POLICY_V1",block.chainid,address(this),controller,
            entry,maintenance,gasLimits,sale,metadata));
    }

constructor(address source, bytes32 codeHash, bytes32 id, int32 exponent,
        uint32 age, uint16 confidenceBps, bytes32 review) {
        if (source.code.length == 0 || codeHash == bytes32(0) || source.codehash != codeHash ||
            id == bytes32(0) || review == bytes32(0) || exponent < -18 || exponent > 0 ||
            age == 0 || age > 1 days || confidenceBps > MAX_CONFIDENCE_BPS) {
            revert InvalidConfiguration();
        }
        core = source;
        expectedCoreCodeHash = codeHash;
        feedId = id;
        expectedExponent = exponent;
        maxAge = age;
        maxConfidenceBps = confidenceBps;
        decimals = uint8(uint32(-exponent));
        reviewHash = review;
    }

constructor(address controller) ZZZExactLPRewardsCanonical(controller) {
        canonicalModule = address(new ZZZRewardsCanonical(controller));
    }

constructor(address controller) ZZZModule(controller) {
        // Parent runtime is still under construction: msg.sender itself is the
        // immutable identity, not an operator-supplied address or mutable setter.
        rewards=IExactLPRewardsParent(msg.sender);
    }

constructor(bytes memory data) {
        if (data.length > 24573) revert DataTooLong();
        bytes memory runtime = abi.encodePacked(hex"5f5ffd",data);
        assembly ("memory-safe") { return(add(runtime,32),mload(runtime)) }
    }

constructor() {
        controller = msg.sender;
        bytes memory code = type(ZZZRoyaltyRewards).creationCode;
        uint256 length = code.length;
        if (length == 0 || length > 2 * PART_DATA_LIMIT) revert InvalidCreationCode();
        royaltyCodeHash = keccak256(code);
        creationCodeLength = length;
        uint256 first = length > PART_DATA_LIMIT ? PART_DATA_LIMIT : length;
        (part0,part0CodeHash) = _storePart(code,0,first);
        // Exactly two authenticated children, including a prefix-only second
        // child if a future source payload fits entirely in the first part.
        (part1,part1CodeHash) = _storePart(code,first,length-first);
    }

constructor(address nftController) {
        // The NFT may deploy this receiver from its own constructor.
        if (nftController == address(0)) revert InvalidConfiguration();
        nft = nftController;
        creator = msg.sender;
        isAsset[address(0)] = true;
        assets.push(address(0));
        accounted[address(0)] = address(this).balance;
        orphaned[address(0)] = address(this).balance;
        emit AssetAdded(address(0), address(this).balance);
    }

constructor(address controller,address collection,address seaDropImplementation,bytes32 expectedCodeHash)
        ZZZModule(controller) {
        if(collection.code.length==0 || ISeaDropMintCollection(collection).access()!=controller ||
            ISeaDropMintCollection(collection).mintedCount()!=0 || seaDropImplementation.code.length==0 ||
            expectedCodeHash==bytes32(0) || seaDropImplementation.codehash!=expectedCodeHash ||
            access.protocolPolicy().code.length==0) revert InvalidConfiguration();
        nft=collection;seaDrop=seaDropImplementation;seaDropCodeHash=expectedCodeHash;
    }

constructor(address controller,address portfolio,address confirmation) ZZZModule(controller) {
        if(portfolio.code.length == 0 || confirmation.code.length == 0 ||
            address(ZZZPortfolioPolicy(portfolio).access()) != controller ||
            ZZZPortfolioPolicy(portfolio).PORTFOLIO_VERSION() != 2 ||
            address(ZZZRebalanceConfirmation(confirmation).access()) != controller ||
            ZZZRebalanceConfirmation(confirmation).REBALANCE_CONFIRMATION_VERSION() != 3) revert InvalidConfiguration();
        portfolioPolicy = ZZZPortfolioPolicy(portfolio);
        rebalanceConfirmation = ZZZRebalanceConfirmation(confirmation);
    }

constructor(Config memory c) {
        if (c.reviewHash == bytes32(0) || c.zzz == address(0) ||
            Currency.unwrap(c.key.currency0) != address(0) || Currency.unwrap(c.key.currency1) != c.zzz ||
            address(c.key.hooks) != address(0) || c.key.fee >= 1_000_000 ||
            c.key.tickSpacing < TickMath.MIN_TICK_SPACING || c.key.tickSpacing > TickMath.MAX_TICK_SPACING ||
            c.maxETHAge == 0 || c.maxETHAge > 1 days || c.minimumLiquidity == 0 ||
            c.ethUsdFeed == c.stateView || c.ethUsdFeed == c.core) revert InvalidConfiguration();
        bytes32 id = keccak256(abi.encode(c.key));
        if (id != c.expectedPoolId) revert InvalidConfiguration();
        _pins(c);
        uint256 d = _word(c.zzz,abi.encodeWithSelector(DECIMALS));
        uint256 e = _word(c.ethUsdFeed,abi.encodeWithSelector(DECIMALS));
        if (d > 18 || e > 18 || _word(c.stateView,abi.encodeWithSelector(MANAGER)) != uint160(c.core))
            revert InvalidConfiguration();
        zzzDecimals = uint8(d); ethFeedDecimals = uint8(e); poolId = id; settings = c;
    }

constructor(address controller, uint256 nftHomeChain, address budget)
        ZZZModule(controller) {
        if (nftHomeChain == 0 || nftHomeChain != block.chainid || access.protocolPolicy().code.length == 0) {
            revert InvalidConfiguration();
        }
        if (budget.code.length == 0 || address(ZZZMigrationBudget(budget).access()) != controller ||
            ZZZMigrationBudget(budget).IDLE_COMPOUNDING_VERSION() != 4) revert InvalidConfiguration();
        canonicalChainId = nftHomeChain;
        migrationBudget = ZZZMigrationBudget(budget);
    }

constructor(address controller, address vaultController, uint256 chain) {
        access = IZZZAccess(controller);
        if (vaultController.code.length == 0 || IZZZAccess(controller).module(Ids.VAULT) != vaultController ||
            chain == 0 || IZZZVault(vaultController).canonicalChainId() != chain ||
            ICanonicalVaultState(vaultController).ACCOUNTING_VERSION() != 7) revert InvalidState();
        vault = ICanonicalVaultState(vaultController);
        originChain = chain;
        originVault = vaultController;
    }
